create or replace function public.create_tournament_atomic(p_name text,p_description text,p_format text,p_max_players smallint,p_starts_at timestamptz,p_visibility text,p_entry_information text,p_game_title text,p_prize_pool numeric,p_teams jsonb,p_fixtures jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare t uuid; row jsonb; f jsonb; home_id uuid; away_id uuid; begin if auth.uid() is null then raise exception 'Not authenticated'; end if; if char_length(btrim(p_name))<3 then raise exception 'Tournament name must be at least 3 characters.'; end if; if p_max_players<2 or p_max_players>128 then raise exception 'Maximum teams must be between 2 and 128.'; end if; if p_prize_pool is null or p_prize_pool<0 then raise exception 'Prize pool cannot be negative.'; end if; if jsonb_array_length(p_teams)<2 or jsonb_array_length(p_teams)>128 then raise exception 'Tournament must have between 2 and 128 teams.'; end if; insert into public.tournaments(organizer_id,name,description,format,max_players,starts_at,visibility,entry_information,game_title,prize_pool) values(auth.uid(),btrim(p_name),coalesce(p_description,''),p_format,p_max_players,p_starts_at,p_visibility,coalesce(p_entry_information,''),coalesce(nullif(btrim(p_game_title),''),'Football'),p_prize_pool) returning id into t; for row in select value from jsonb_array_elements(p_teams) loop insert into public.tournament_teams(tournament_id,builtin_team_id,team_name,short_name,country,league,city,crest_path,seed) values(t,nullif(row->>'builtin_team_id',''),btrim(row->>'team_name'),btrim(row->>'short_name'),coalesce(row->>'country',''),coalesce(row->>'league',''),coalesce(row->>'city',''),nullif(row->>'crest_path',''),(row->>'seed')::smallint); end loop; for f in select value from jsonb_array_elements(coalesce(p_fixtures,'[]'::jsonb)) loop select id into home_id from public.tournament_teams where tournament_id=t and seed=(f->>'home_seed')::smallint limit 1; select id into away_id from public.tournament_teams where tournament_id=t and seed=(f->>'away_seed')::smallint limit 1; insert into public.fixtures(tournament_id,round_number,position,round_label,group_name,home_team_id,away_team_id,status) values(t,(f->>'round_number')::smallint,(f->>'position')::smallint,coalesce(f->>'round_label',''),nullif(f->>'group_name',''),home_id,away_id,'pending'); end loop; return t; end; $$; grant execute on function public.create_tournament_atomic(text,text,text,smallint,timestamptz,text,text,text,numeric,jsonb,jsonb) to authenticated;
